function smallestNumber(pattern: string): string {
    const n = pattern.length;
    const res = new Array(n + 1).fill('');
    const vis = new Array(n + 1).fill(false);
    const dfs = (i: number, num: number) => {
        if (i === n) {
            return;
        }

        if (vis[num]) {
            vis[num] = false;
            if (pattern[i] === 'I') {
                dfs(i - 1, num - 1);
            } else {
                dfs(i - 1, num + 1);
            }
            return;
        }

        vis[num] = true;
        res[i] = num;

        if (pattern[i] === 'I') {
            for (let j = res[i] + 1; j <= n + 1; j++) {
                if (!vis[j]) {
                    dfs(i + 1, j);
                    return;
                }
            }
            vis[num] = false;
            dfs(i, num - 1);
        } else {
            for (let j = res[i] - 1; j > 0; j--) {
                if (!vis[j]) {
                    dfs(i + 1, j);
                    return;
                }
            }
            vis[num] = false;
            dfs(i, num + 1);
        }
    };
    dfs(0, 1);
    for (let i = 1; i <= n + 1; i++) {
        if (!vis[i]) {
            res[n] = i;
            break;
        }
    }

    return res.join('');
}

//https://leetcode.com/problems/construct-smallest-number-from-di-string/

package construct_smallest_number_from_di_string

import (
	"container/list"
	"fmt"
)

type State struct {
	pos    int
	num    int
	result string
	count  []int
}

func (s *State) IsValid() bool {
	for i := 0; i < len(s.count); i++ {
		if s.count[i] > 1 {
			return false
		}
	}
	return true
}

func smallestNumber(pattern string) string {
	q := list.New()
	for i := 1; i < 10; i++ {
		s := State{
			pos:    0,
			num:    i,
			result: fmt.Sprintf("%d", i),
			count:  make([]int, 10),
		}
		s.count[i] = 1
		q.PushBack(s)
	}

	for q.Len() > 0 {
		cur := q.Front().Value.(State)
		q.Remove(q.Front())
		if cur.pos == len(pattern) {
			return cur.result
		}
		if pattern[cur.pos] == 'I' {
			for i := cur.num + 1; i < 10; i++ {
				s := State{
					pos:    cur.pos + 1,
					num:    i,
					result: cur.result + fmt.Sprintf("%d", i),
					count:  make([]int, 10),
				}
				copy(s.count, cur.count)
				s.count[i]++
				if s.IsValid() {
					q.PushBack(s)
				}
			}
		} else {
			for i := 1; i < cur.num; i++ {
				s := State{
					pos:    cur.pos + 1,
					num:    i,
					result: cur.result + fmt.Sprintf("%d", i),
					count:  make([]int, 10),
				}
				copy(s.count, cur.count)
				s.count[i]++
				if s.IsValid() {
					q.PushBack(s)
				}
			}
		}
	}

	return ""
}

//Approach 1: Using stack. TC: O(n) SC: O(n)
//Editorial: https://leetcode.com/problems/construct-smallest-number-from-di-string/discuss/2422180/C++-Clean-Stack-Solution
class Solution {
public:
    string smallestNumber(string pattern) {
        int n=pattern.size();
        stack<int> stk;
        string ans="";
        for(int i=0;i<=n;i++)
        {
            stk.push(i+1);
            if(i==n or pattern[i]=='I')
            {
                while(!stk.empty())
                {
                    ans+=to_string(stk.top());
                    stk.pop();
                }
            }
        }
        return ans;
    }
};
//Approach 2: Using reverse function. TC: O(n) SC: O(1)
//Editorial: https://leetcode.com/problems/construct-smallest-number-from-di-string/discuss/2422290/DFS-vs.-Greedy
class Solution {
public:
    string smallestNumber(string pattern) {
        string ans="";
        int n=pattern.size();
        for(int i=0,j=0;i<=n;i++)
        {
            ans+=(i+'1');
            if(i==n or pattern[i]=='I')
            {
                reverse(ans.begin()+j,ans.end());
                j=i+1;
            }
        }
        return ans;
    }
};
